ara ride on globaladv for now."},"sis_present":[{"si":"culture","name":"culture","status":"live","note":"Jemaa el-Fnaa, medina/souks, Koutoubia, Bahia, Majorelle/YSL, Saadian Tombs"},{"si":"culinary","name":"culinary","status":"live","note":"Moroccan cuisine, cooking classes, food tours"},{"si":"wellness","name":"wellness","status":"live","note":"hammam + riad/Royal Mansour spa"},{"si":"golf","name":"Golf Globally","status":"live","note":"~11 courses - Royal, Assoufid, Amelkis, Al Maaden"}],"ultra":[{"name":"A Royal Mansour private riad + private medina + Agafay sunset camp","why_ultra":"your own three-story riad, an after-hours palace visit, and a luxury tented dinner under the stars","earning":"consortia/DMC","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,400-3,000+/night"}],"source_verified":"2026-08-03","hero":{"query":"Marrakech, Morocco"},"geo":{"lat":31.6295,"lng":-7.9811}}'::jsonb, 12)
