  ('wadi-rum-jordan', '04A', 'Wadi Rum', 'Jordan', 'The Valley of the Moon', 'live', 'verified', 'desertDunes', 'Jordan & the Levant', '{"adventure","ultra","culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'anchor', '{"key_facts":["The Valley of the Moon - a 74,000-ha sandstone-and-granite desert; UNESCO World Heritage since 2011 (a MIXED cultural + natural site)","Bedouin country - classic goat-hair tents through to luxury bubble/dome camps under some of the clearest night skies on Earth","Jeep safaris, camel treks, rock climbing, ancient rock art, and film-set fame (Lawrence of Arabia country; a favorite desert-planet backdrop)","Wadi Rum entry is included in the Jordan Pass; an hour south of Petra - the two make one trip","US Level 3 Reconsider Travel (March 2026); the Level-4 areas are the Syria/Iraq borders - Wadi Rum is in the deep south, far from them","Best season March-April & October-November; summer days ~40C, winter nights can drop below freezing"],"safety":{"emergency":"911 (unified - police / ambulance / civil defense); Tourist Police +962 79 550 5755","hospital":"Aqaba + Amman for major referral; carry travel-medical + evac insurance","advisory_level":"L3","activity_note":"L3 Reconsider Travel - disclose prominently. Level-4 areas = Syria/Iraq borders (far north/east); Wadi Rum is in the deep south, far from them. Extreme day heat / cold nights; go with a registered Bedouin camp/guide; water + sun cover; guided rock climbing only.","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel to within 3km of the border with Syria."},{"form":"against all travel","text":"advises against all travel to Syria."},{"form":"against all travel","text":"advises against all travel to Iraq ."},{"form":"against all travel","text":"advises against all travel to the provinces in Iraq bordering Jordan."},{"form":"against all but essential travel","text":"advises against all but essential travel Aqaba Governate FCDO advises against all but essential travel to Aqaba international airport and seaport."},{"form":"against all but essential travel","text":"advises against all but essential travel to Aqaba international airport and seaport."}],"url":"https://www.gov.uk/foreign-travel-advice/jordan","read":"2026-08-19","page_updated":"2026-07-22T13:47:55+01:00"}},"timing":{"peak":"Mar-Apr & Oct-Nov (warm days, cool nights)","shoulder":"Mar + Nov","green":"Jun-Aug (~40C days, dawn/dusk touring) + Dec-Feb (freezing nights, quiet)","booking_lead":"luxury bubble camps capacity-tight in peak - book well ahead","off_season_specials":"summer + winter value; pair with Petra + Dead Sea + Amman","event_peaks":"spring + autumn peak; clear-sky stargazing year-round","campaign_start":"sell spring/autumn desert nights 2-4 mo out; lead EN + GCC + DE; stargazing + luxury-camp angles"},"jewels":[{"name":"A night in a glass bubble under the Milky Way","si_tag":"ultra","status":"live","tier":"premier","price_band":"book ahead","timing":"Mar-Nov","draw_rank":1,"hook":"luxury dome camps with clear-sky stargazing — Wadi Rum''s signature high-margin stay","si":"ultra","blurb":"luxury dome camps with clear-sky stargazing — Wadi Rum''s signature high-margin stay","when":"Mar-Nov","commission":"DMC/consortia 10-16%"},{"name":"A dawn 4x4 safari across the red sand","si_tag":"globaladv","status":"live","tier":"essential","price_band":"within the stay","timing":"Mar-Apr & Oct-Nov","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dunes, arches, canyons, and rock art with a Bedouin driver-guide","si":"adventure","blurb":"dunes, arches, canyons, and rock art with a Bedouin driver-guide","when":"Mar-Apr & Oct-Nov","commission":"DMC 10-15%"},{"name":"A Bedouin camp dinner + fire (zarb feast)","si_tag":"culture","status":"live","tier":"essential","price_band":"within the stay","timing":"Mar-Apr & Oct-Nov","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Mar-Apr & Oct-Nov","commission":"within the stay"}],"faq":[{"q":"What is Wadi Rum?","a":"A vast protected desert of red sand and towering sandstone in southern Jordan - Bedouin camps, jeep and camel safaris, rock climbing, ancient rock art, and a night sky that draws stargazers. UNESCO mixed (cultural + natural) World Heritage since 2011.","source":"whc.unesco.org","si_tag":"globaladv"},{"q":"Can you sleep in the desert at Wadi Rum?","a":"Yes - from classic Bedouin goat-hair tents to luxury glass bubble and dome camps with clear-sky stargazing. The luxury camps are the signature high-end stay and are capacity-tight in spring and autumn, so book well ahead.","source":"unesco datasheet","si_tag":"ultra"},{"q":"When is the best time to visit Wadi Rum?","a":"March-April and October-November - warm days and cool desert nights. Summer days reach about 40C (tour at dawn and dusk); winter nights can drop below freezing.","source":"responsibletravel.com","si_tag":"globaladv"}],"seo":{"meta_title":"Wadi Rum Guide: Bubble Camps, Jeep Safaris & Safety - Best Time to Visit (2026)","meta_description":"Plan Wadi Rum - the Valley of the Moon, luxury bubble camps under the stars, Bedouin jeep and camel safaris, UNESCO mixed World Heritage, best season spring/autumn, with straight Level-3 safety intel.","slug":"wadi-rum-jordan","primary_keyword":"Wadi Rum Jordan","long_tail":["Wadi Rum bubble camp","Wadi Rum jeep safari","is Wadi Rum safe","Wadi Rum stargazing","best time to visit Wadi Rum","Wadi Rum luxury camp"],"search_language":"en","local_keywords":["Wadi Rum","Valley of the Moon","Bedouin","Disi","Rum village"],"hreflang":["en","ar","de"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-03"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","regional-tensions","terrorism"],"book_suppressed":false,"note":"Jordan US Level 3 Reconsider Travel (escalated March 2026, regional US-Iran tensions). Disclose PROMINENTLY; heightened-consent booking. Level-4 Do-Not-Travel areas = Syria + Iraq border strips + Mansheyat al Ghayyath + Ruwayshid - Wadi Rum is in the DEEP SOUTH, far from them. Operators run desert camps + tours through 2026. Re-verify each cycle (may revert to L2)."},"si_checklist_25":{"run_date":"2026-08-03","hits":3,"misses":18,"disregarded":3,"note":"Desert adventure + ultra: adventure (jeep/camel/climb) + ultra (bubble/dome camps) + culture (Bedouin/UNESCO mixed) live; deepdive (Bedouin ethnography) future. glamping SI not live - luxury camps ride on ultra + adventure. sub_region ''Jordan & Petra'' PROPOSED. US L3 - disclose."},"sis_present":[{"si":"globaladv","name":"adventure","status":"live","note":"jeep safari, camel trek, rock climbing/scrambling, guided stargazing"},{"si":"ultra","name":"ultra","status":"live","note":"luxury bubble/dome desert camps under clear skies - high-margin signature stay"},{"si":"culture","name":"culture","status":"live","note":"Bedouin hospitality + UNESCO mixed World Heritage (2011, 74,000 ha), ancient rock art"}],"ultra":[{"name":"A luxury bubble-dome camp + private jeep + private stargazing guide","why_ultra":"a glass suite open to the sky, a private dawn drive, and an astronomer-led night, an hour from Petra","earning":"consortia/DMC","virtuoso_value_add":false,"mor":"commissionable-rack","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-03","hero":{"query":"Wadi Rum, Jordan"},"geo":{"lat":29.5765,"lng":35.4207}}'::jsonb, 19),
