  ('serengeti-tanzania', '05A', 'Serengeti National Park', 'Tanzania', 'The greatest wildlife show on Earth', 'live', 'verified', 'safariGiraffe', 'Tanzania — Northern Safari Circuit / Serengeti', '{"safari","ultra","romance","adventure","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["The safari demo STAR: UNESCO 1981, world''s highest concentration of large predators + Africa''s largest lion population; the Great Migration - ~2M wildebeest + ~300k zebra + ~900k Thomson''s gazelles on a ~1,000 km annual circuit","Migration clock: Ndutu calving Jan-Feb (~500k calves in 2-3 wks); Grumeti crossings Jun (western); Mara River crossings Jul-Oct peak Aug-Sep (northern/Kogatende); Sept = best balance","Best general game-viewing dry season late Jun-Oct; 3-5 days typical; ~$600-2,700+/pp/day by comfort; book 6-12 mo ahead for peak","US L3 Reconsider Travel (terrorism concern = Mtwara far south, NOT the safari circuit; LGBTQ+ targeting flagged); safari one of Africa''s safest with a licensed operator - disclose L3 + consent","Sold via safari DMCs - IATAN/host-gated NOT CLIA; commission ~10-20%; TANAPA park fees non-commissionable; AMREF Flying Doctors (~$40 pp/30d) for remote evac","TZS (~2,633/USD) but USD is the safari currency; eVisa required; malaria prophylaxis recommended (lower risk at elevation); YF only if transiting a risk country (e.g. Kenya) >12h"],"safety":{"emergency":"112 / 999 (unreliable in remote areas - rely on camp/operator radio + AMREF Flying Doctors)","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d, bush-airstrip evac; NOT hospital/repatriation) + travel-medical insurance; nearest referral Arusha","advisory_level":"L3","malaria":"prophylaxis recommended (CDC) - lower risk at 920-1,800m elevation but present; DEET + cover at dusk","yellow_fever":"not required from a non-risk country; mandatory if transiting >12h a risk country (e.g. Kenya)","activity_note":"L3 DISCLOSE + CONSENT (terrorism = Mtwara far south, NOT the circuit; LGBTQ+ targeting flagged). DANGEROUS-GAME country: stay in the vehicle except designated areas, follow the guide; walking safari armed-ranger only; balloon TCAA-inspected; remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel to parts of Tanzania Tanzania FCDO advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."},{"form":"against all but essential travel","text":"advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."}],"url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-08-19","page_updated":"2026-05-19T15:47:49+01:00"}},"timing":{"peak":"Jul-Oct (dry + Mara River crossings, Aug-Sep drama); secondary Jan-Feb (Ndutu calving)","shoulder":"Jun (Grumeti crossings, less crowded) + Nov (short rains, herds moving south)","green":"Mar-May (long rains - lush, quiet, cheapest; some camps close)","booking_lead":"6-12 mo for Jul-Sep peak + calving (premium/mobile camps sell out); mid-range 3-6 mo; green 1-3 mo","off_season_specials":"Mar-May green-season value + Grumeti-crossing (Jun) shoulder; combine Ngorongoro/Tarangire","event_peaks":"Jul-Sep Mara-crossing crush + Jan-Feb calving; Christmas/NY + Easter; N-Hemisphere summer","campaign_start":"Jul-Sep crossings 9-12 mo out (by prior Oct-Dec); Jan-Feb calving by prior Apr-Jun; green-season value by prior Nov-Dec"},"jewels":[{"name":"The Great Migration - Mara River crossings","si_tag":"safari","status":"live","tier":"premier","price_band":"~$1,200-2,700+/pp/day","timing":"Jul-Oct; book 9-12 mo","draw_rank":1,"hook":"the planet''s greatest overland migration at its most dramatic — herds massing and plunging past waiting crocodiles in the northern Serengeti, Jul–Oct, peak Aug–Sep","si":"safari","blurb":"the planet''s greatest overland migration at its most dramatic — herds massing and plunging past waiting crocodiles in the northern Serengeti, Jul–Oct, peak Aug–Sep","when":"Jul-Oct; book 9-12 mo","commission":"safari DMC 10-20%"},{"name":"The Ndutu calving","si_tag":"safari","status":"live","tier":"premier","price_band":"~$1,000-2,500/pp/day","timing":"Jan-Feb; book 6-9 mo","draw_rank":2,"hook":"~500,000 calves born in a 2–3-week window in the southern Ndutu plains — concentrated big-cat action","si":"safari","blurb":"~500,000 calves born in a 2–3-week window in the southern Ndutu plains — concentrated big-cat action","when":"Jan-Feb; book 6-9 mo","commission":"safari DMC 10-20%"},{"name":"Big-cat & Big Five game drives (Seronera)","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$600-1,800/pp/day","timing":"year-round; dry Jun-Oct best","draw_rank":3,"hook":"the highest predator density on Earth — lion prides, cheetah on the plains, leopard in the kopjes","si":"safari","blurb":"the highest predator density on Earth — lion prides, cheetah on the plains, leopard in the kopjes","when":"year-round; dry Jun-Oct best","commission":"safari DMC 10-20%"},{"name":"The Grumeti crossings (Western Corridor)","si_tag":"safari","status":"live","tier":"premier","price_band":"~$1,000-2,200/pp/day","timing":"Jun","draw_rank":4,"hook":"June''s first major crossings on the Grumeti — less famous, less crowded, equally wild — a shoulder-season alternative to the Mara crush","si":"safari","blurb":"June''s first major crossings on the Grumeti — less famous, less crowded, equally wild — a shoulder-season alternative to the Mara crush","when":"Jun","commission":"safari DMC 10-20%"},{"name":"Dawn hot-air balloon safari + bush breakfast","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$550-650/pp","timing":"Jul-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the signature Serengeti moment — sunrise over the plains from a balloon, then a champagne bush breakfast; TCAA-inspected operators","si":"adventure","blurb":"the signature Serengeti moment — sunrise over the plains from a balloon, then a champagne bush breakfast; TCAA-inspected operators","when":"Jul-Oct","commission":"DMC/camp 10-15%"},{"name":"Guided walking safari (armed ranger)","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$100-200/pp","timing":"Jul-Oct","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Serengeti on foot — tracks, dung, birdsong and the adrenaline of dangerous-game country with an armed ranger","si":"adventure","blurb":"the Serengeti on foot — tracks, dung, birdsong and the adrenaline of dangerous-game country with an armed ranger","when":"Jul-Oct","commission":"camp/DMC"},{"name":"A migration-following luxury mobile camp","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$1,500-4,000+/night all-in","timing":"standing; peak 9-12 mo","draw_rank":1,"hook":"the ultra way to do the migration — Singita, &Beyond, Nomad and Namiri Plains move their tented camps to the herds","si":"ultra","blurb":"the ultra way to do the migration — Singita, &Beyond, Nomad and Namiri Plains move their tented camps to the herds","when":"standing; peak 9-12 mo","commission":"consortia/Virtuoso + DMC"},{"name":"Honeymoon safari - star bed + bush dinner","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jul-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"sundowners on the plains, a private bush dinner under the lanterns, a sleep-out under the Milky Way — the romance of the wild","si":"romance","blurb":"sundowners on the plains, a private bush dinner under the lanterns, a sleep-out under the Milky Way — the romance of the wild","when":"Jul-Oct","commission":"consortia/host"},{"name":"A Maasai cultural visit","si_tag":"culture","status":"future","tier":"essential","price_band":"~$20-60/pp","timing":"Jul-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the pastoralist Maasai of the Serengeti–Ngorongoro edge — a visit to a boma, the dances and the beadwork, done with a respectful, fair-trade operator","si":"culture","blurb":"the pastoralist Maasai of the Serengeti–Ngorongoro edge — a visit to a boma, the dances and the beadwork, done with a respectful, fair-trade operator","when":"Jul-Oct","commission":"DMC/community"}],"faq":[{"q":"What''s the real risk to plan for on a Serengeti safari?","a":"Not the parks - remoteness and wildlife discipline. Big game is genuinely dangerous: stay in the vehicle except in designated areas and follow your guide. The Serengeti is remote, so pair travel-medical insurance with AMREF Flying Doctors (~$40 pp/30 days) for bush-airstrip evacuation. City petty crime, not park danger, is the everyday risk.","source":"flydoc.org","si_tag":"safety"},{"q":"Should LGBTQ+ travelers be aware of anything in Tanzania?","a":"Yes, plainly: Tanzanian law criminalizes same-sex relations and the US advisory specifically flags targeting of LGBTQ+ travelers. It''s a real safety consideration to weigh; discretion is advised, and we''ll talk it through candidly before you book.","source":"newsweek.com","si_tag":"safety"},{"q":"When is the best time to see the Great Migration?","a":"General game-viewing is best in the dry season (late Jun-Oct). For the Mara River crossings, come Jul-Oct (peak Aug-Sep); for calving and big-cat drama, come Jan-Feb to the southern Ndutu plains. September is the best all-round balance of action and lighter crowds.","source":"dumaexplorer.com","si_tag":"safari"},{"q":"How many days do I need and what does a Serengeti safari cost?","a":"Plan 3-5 days (often combined with Ngorongoro/Tarangire). All-in cost runs roughly $600-1,000/day budget, $1,200-1,500 mid-range, $1,400-2,700+ luxury per person; book 6-12 months ahead for the Jul-Sep peak - premium camps sell out.","source":"bucketlistly.blog","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for the Serengeti?","a":"A visa (eVisa) - apply on the official Tanzania portal before departure (~2-10 days). Yellow fever isn''t required arriving directly from the US/Europe, but becomes mandatory if you transit >12h through a risk country like Kenya - key for Kenya-Tanzania combos.","source":"tanzania-specialist.com","si_tag":"safari"}],"seo":{"meta_title":"Serengeti Safari Guide: The Great Migration, River Crossings, Best Time & Safety (Level 3)","meta_description":"Plan a Serengeti safari - the Great Migration (~2M wildebeest), the Mara River crossings (Jul-Oct) and Ndutu calving (Jan-Feb), the highest big-cat density on Earth, dawn balloon flights and luxury migration camps - with real timing, cost, the US Level-3 advisory, malaria and evac intel.","slug":"serengeti-tanzania","primary_keyword":"Serengeti safari","long_tail":["Great Migration Serengeti 2026","Mara River crossings best time","Ndutu calving season","Serengeti balloon safari","is the Serengeti safe","Serengeti safari cost","best time to visit Serengeti"],"search_language":"sw","local_keywords":["Serengeti","Uhamiaji Mkubwa","Mto Mara","Ndutu","pundamilia","nyumbu","simba","safari ya puto"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-31"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","terrorism-mtwara","crime","lgbtq-targeting"],"book_suppressed":false,"note":"Tanzania US L3 Reconsider Travel - the terrorism concern is the Mtwara Region (far south), NOT the northern safari circuit; Serengeti is one of Africa''s safest safaris with a licensed operator. Disclose L3 + confirm consent before booking. LGBTQ+ travelers: same-sex relations criminalized + advisory flags targeting - surface plainly. Re-verify each publish cycle."},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - the park is primary safari (not globaladv); globaladv carries the balloon/walking add-ons; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live"},{"si":"ultra","name":"ultra","status":"live"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"globaladv","name":"adventure","status":"live","note":"balloon + walking safari add-ons"},{"si":"culture","name":"culture","status":"future","note":"Maasai"}],"ultra":[{"name":"Singita Grumeti / Namiri Plains - apex Serengeti stay","why_ultra":"private-concession luxury, exclusive game, butlered tented suites - the migration to yourself","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$2,000-4,000+/night"},{"name":"A private migration mobile camp + private guide + balloon","why_ultra":"exclusive-use mobile camp that moves with the herds, private vehicle/guide + the dawn balloon","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A Northern-Circuit private-guided week (Serengeti + Ngorongoro + Tarangire)","why_ultra":"private guide + vehicle across the marquee parks, luxury camps throughout","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-07-31","hero":{"query":"Serengeti National Park, Tanzania"},"geo":{"lat":-2.3333,"lng":34.8333}}'::jsonb, 1),
  ('volcanoes-national-park-rwanda', '05A', 'Volcanoes National Park', 'Rwanda', 'Gorillas in the mist', 'live', 'verified', 'safariGiraffe', 'Rwanda — Volcanoes / Virunga', '{"safari","adventure","ultra","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Rwanda''s flagship mountain-gorilla trek (the wow) in the Virunga volcanoes - a one-hour habituated-family encounter; world mountain-gorilla population now 1,063 (no longer critically endangered); the birthplace of African conservation (Dian Fossey/Karisoke 1967)","Permit $1,500/trekker (RDB), only 98/day, sells out - book 3-6 months ahead via a licensed operator or RDB (Irembo); min age 15; ~2h from Kigali - the accessible, premium gorilla trek","Also: golden-monkey trekking (bamboo), Mount Bisoke crater-lake hike (3,711m, most popular), Karisimbi summit (4,507m, Rwanda''s highest, 2-day), Dian Fossey grave hike, Kwita Izina gorilla-naming (Sep)","US L3 Reconsider Travel (2026 regional Ebola-alert; was L2) - bookable disclose+consent; PLUS a standing US L4 carve-out within 10km of the DRC border (Volcanoes'' sectors/lodges are on the Rwandan side)","UGANDA IS L4 (Ebola) - Rwanda Volcanoes is the LIVE gorilla redirect; gorilla trek = strenuous high-altitude (~2,500-3,700m) muddy rainforest hike (moderate fitness); trekking rules: 7m distance, mask, max 1hr, max 8/group, armed ranger, no trekking if ill","Sold via Rwandan safari DMCs 10-20% - IATAN/host-gated, CLIA has NO Africa representation; the $1,500 RDB permit is non-commissionable pass-through; RWF (~1,467/USD); visa on arrival $30; malaria year-round (prophylaxis); AMREF for evac"],"safety":{"emergency":"112 (police) / 912 ambulance / 111 fire; AMREF Flying Doctors for high-terrain evac","hospital":"Remote/high terrain - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Musanze/Kigali","advisory_level":"L3","malaria":"present year-round (chloroquine-resistant) - prophylaxis advised; DEET at dusk (lower at altitude but real)","yellow_fever":"required only if arriving from a YF-endemic country (not direct from the US)","activity_note":"L3 DISCLOSE + CONSENT (2026 regional Ebola-alert precaution). Standing US L4 within 10km of the DRC border - route to the Rwandan-side sectors/lodges, not the border. Gorilla trek = strenuous high-altitude (~2,500-3,700m) muddy hike (moderate fitness); rules: 7m/1hr/mask/max 8/armed ranger/no trekking if ill. Volcano climbs = altitude sickness risk. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Rusizi District FCDO advises against all but essential travel to the parts of Rusizi District which are within 10km of the border with the Democratic Republic of Congo (DRC), including the Rwandan islands in Lake Kivu and Kamembe Airport."},{"form":"against all but essential travel","text":"advises against all but essential travel to parts of the Rubavu and Rusizi Districts."}],"url":"https://www.gov.uk/foreign-travel-advice/rwanda","read":"2026-08-19","page_updated":"2026-06-10T15:14:19+01:00"}},"timing":{"peak":"Jun-Sep + Dec-Feb (drier, firmer trails; permits sell out; Kwita Izina Sep spikes demand)","shoulder":"early Mar + late Nov (softer)","green":"Mar-May + Oct-Nov (rains - lush, muddier; 30% low-season permit discount Nov-May IF you also pre-book Akagera and/or Nyungwe nights)","booking_lead":"permits + luxury lodges 3-6 mo (Jun-Sep + Dec-Feb sell out; only 98 permits/day); green 1-3 mo","off_season_specials":"the Nov-May 30%-off permit (with Akagera/Nyungwe nights) - sell a 3-park Rwanda circuit to unlock it","event_peaks":"Kwita Izina (Sep) + Christmas/NY + Jun-Sep dry","campaign_start":"Jun-Sep + Dec-Feb 6-9 mo out; Nov-May discounted 3-park circuit by prior Aug-Sep; position as the Uganda-L4 gorilla redirect now"},"jewels":[{"name":"The mountain-gorilla trek","si_tag":"safari","status":"live","tier":"premier","price_band":"~$1,000-3,000+/pp/day (permit-inclusive)","timing":"year-round; Jun-Sep + Dec-Feb peak; book 3-6 mo","draw_rank":1,"hook":"the single most moving hour in wildlife travel","si":"safari","blurb":"the single most moving hour in wildlife travel","when":"year-round; Jun-Sep + Dec-Feb peak; book 3-6 mo","commission":"DMC 10-20% (permit pass-through)"},{"name":"Kwita Izina - the gorilla-naming ceremony","si_tag":"safari","status":"live","tier":"premier","price_band":"event + trek","timing":"September","draw_rank":2,"hook":"Rwanda''s global conservation celebration each September — newborn gorillas named before thousands; a rare, meaningful event to time a trip around","si":"safari","blurb":"Rwanda''s global conservation celebration each September — newborn gorillas named before thousands; a rare, meaningful event to time a trip around","when":"September","commission":"DMC + event"},{"name":"Golden-monkey trekking","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$100/pp","timing":"Jun-Sep + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Virungas'' other primate — troops of endangered golden monkeys in the bamboo, a budget-friendlier, joyful half-day","si":"adventure","blurb":"the Virungas'' other primate — troops of endangered golden monkeys in the bamboo, a budget-friendlier, joyful half-day","when":"Jun-Sep + Dec-Feb","commission":"DMC/RDB"},{"name":"Mount Bisoke crater-lake hike + Karisimbi summit","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$75-400/pp","timing":"dry season; guided","draw_rank":2,"hook":"the park''s most popular hike to Bisoke''s crater lake, or the strenuous 2-day summit of Karisimbi — volcano-country adventure between gorilla days","si":"adventure","blurb":"the park''s most popular hike to Bisoke''s crater lake, or the strenuous 2-day summit of Karisimbi — volcano-country adventure between gorilla days","when":"dry season; guided","commission":"DMC/RDB"},{"name":"The Dian Fossey grave hike (Karisoke)","si_tag":"deepdive","status":"future","tier":"premier","price_band":"~$75/pp","timing":"Jun-Sep + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a pilgrimage through the forest to Fossey''s grave beside her gorilla Digit, at the site of the 1967 Karisoke Research Center","si":"deepdive","blurb":"a pilgrimage through the forest to Fossey''s grave beside her gorilla Digit, at the site of the 1967 Karisoke Research Center","when":"Jun-Sep + Dec-Feb","commission":"DMC/RDB"},{"name":"A gorilla-lodge honeymoon (Singita / One&Only / Bisate)","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$1,500-5,000+/night all-in","timing":"standing; peak 3-6 mo","draw_rank":1,"hook":"the Virungas'' apex lodges — Singita Kwitonda''s volcano-view suites, One&Only Gorilla''s Nest, Bisate''s cone-shaped villas — fireside luxury after the trek; honeymoon-grade","si":"ultra","blurb":"the Virungas'' apex lodges — Singita Kwitonda''s volcano-view suites, One&Only Gorilla''s Nest, Bisate''s cone-shaped villas — fireside luxury after the trek; honeymoon-grade","when":"standing; peak 3-6 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Virunga honeymoon","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Sep + Dec-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Sep + Dec-Feb","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for at Volcanoes?","a":"The trek itself, and the altitude. The gorilla trek is a strenuous, high-altitude (~2,500-3,700m), often muddy rainforest hike — come with moderate fitness; malaria is year-round (prophylaxis + DEET), and it is remote — carry AMREF Flying Doctors + insurance. **FCDO travel advice for Rwanda:** the FCDO advises against all but essential travel to NAMED AREAS — parts of Rusizi District within 10km of the DRC border. *https://www.gov.uk/foreign-travel-advice/rwanda — page updated 2026-06-10. Quoted unchanged; TravelWell does not state whether this destination lies inside a named area.*","source":"cdc.gov","si_tag":"safety"},{"q":"How much is the gorilla permit and how do I book it?","a":"US$1,500 per trekker, and with only 98 permits/day it sells out - book 3-6 months ahead through a licensed operator or the Rwanda Development Board (Irembo). Minimum age 15.","source":"volcanoesnationalpark.org","si_tag":"safari"},{"q":"How hard is the gorilla trek and what are the rules?","a":"Moderate-to-strenuous: 1-7 hours through steep, muddy, high-altitude forest to reach the family, then max 1 hour with them, 7 m minimum distance, a face mask, max 8 per group, an armed ranger, and no trekking if you''re ill. Porters are available and recommended.","source":"visitrwandagorilla.com","si_tag":"safari"},{"q":"Rwanda or Uganda for gorillas in 2026?","a":"Rwanda''s permit is pricier ($1,500 vs Uganda''s $800), and Volcanoes is 2 hours from Kigali. **FCDO travel advice:** for Rwanda the FCDO advises against all but essential travel to named areas (parts of Rusizi District within 10km of the DRC border) — *gov.uk/foreign-travel-advice/rwanda, updated 2026-06-10*. For Uganda the FCDO names no advisory against travel — *gov.uk/foreign-travel-advice/uganda, updated 2026-07-27*. ⛔ Read both before choosing; TravelWell states no preference on safety grounds.","source":"travelweekly.com","si_tag":"safari"},{"q":"When is the best time to visit, and what else can I do?","a":"Best in the drier Jun-Sep and Dec-Feb; beyond the gorillas, track golden monkeys, hike Bisoke''s crater lake, climb Karisimbi, and make the Dian Fossey grave pilgrimage - a 2-3-day stay rewards.","source":"volcanoesparkrwanda.org","si_tag":"globaladv"}],"seo":{"meta_title":"Volcanoes NP Rwanda Gorilla Trekking Guide: Permits, Fitness, Best Time & Safety","meta_description":"Plan a Volcanoes National Park gorilla trek - Rwanda''s flagship mountain-gorilla experience in the Virungas: the $1,500 permit and how to book it, the fitness and rules, Dian Fossey''s Karisoke, golden monkeys and volcano hikes, 2 hours from Kigali - with the US Level-3 advisory, altitude and health intel.","slug":"volcanoes-np-rwanda","primary_keyword":"Volcanoes National Park gorilla trekking","long_tail":["Rwanda gorilla permit cost 2026","gorilla trekking fitness Rwanda","Dian Fossey grave hike","golden monkey trekking Rwanda","Mount Bisoke hike","Rwanda vs Uganda gorillas","is Rwanda safe"],"search_language":"fr","local_keywords":["Parc National des Volcans","ingagi","Karisoke","Bisoke","Karisimbi","Kwita Izina","inguge z''izahabu"],"hreflang":["en","fr"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-01"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","regional-ebola-alert","drc-border-10km-l4-carveout"],"book_suppressed":false,"note":"Rwanda US L3 Reconsider Travel (2026 regional Ebola-alert precaution; was L2). Disclose L3 + confirm consent. Standing US L4 Do Not Travel carve-out within 10km of the DRC border - Volcanoes'' sectors + lodges are on the Rwandan side (route there, not the border). Uganda''s L4 makes Rwanda the LIVE gorilla choice. Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-08-01","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - the mountain-gorilla trek is primary safari; golden monkeys + volcano hikes + Fossey grave hike = globaladv; Fossey/Karisoke conservation legacy = deepdive; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"mountain gorilla trekking"},{"si":"globaladv","name":"adventure","status":"live","note":"golden monkeys + Bisoke/Karisimbi volcano hikes + Dian Fossey grave hike"},{"si":"ultra","name":"ultra","status":"live","note":"Singita/One&Only/Bisate/Sabyinyo"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"Dian Fossey / Karisoke"}],"ultra":[{"name":"Singita Kwitonda / One&Only Gorilla''s Nest - the Virungas'' apex stays","why_ultra":"volcano-view suites, private guiding + butlered luxury at the forest edge, the gorilla trek from the doorstep","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$2,500-5,000+/night"},{"name":"A private double-gorilla-permit + golden-monkey + Fossey week","why_ultra":"two gorilla treks (different families) + golden monkeys + the Fossey grave hike + a Bisoke climb, privately guided from an ultra lodge","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A 3-park Rwanda circuit (Volcanoes + Akagera + Nyungwe)","why_ultra":"gorillas + Big-Five Akagera + Nyungwe chimps/canopy walk, private-guided - and it unlocks the Nov-May 30% permit discount","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-01","hero":{"query":"Volcanoes National Park, Rwanda"},"geo":{"lat":-1.4667,"lng":29.5}}'::jsonb, 2),
  ('akagera-np-rwanda', '05A', 'Akagera National Park', 'Rwanda', 'Rwanda''s Big Five comeback', 'live', 'verified', 'elephant', 'Rwanda — Akagera', '{"safari","adventure","ultra","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Rwanda''s only Big-Five savanna park + one of conservation''s great turnarounds - African Parks (with the RDB since 2010) reintroduced lions (2015), black rhinos (2017), and southern white rhinos in 2021 (30) and 2025 (70, ''Rhino Rewild'')","~1,100 km2 of plains, hills and lakes (largest protected wetland in central/eastern Africa); Big Five game drives + Lake Ihema boat safari (hippos, crocs, ~550 birds incl. the shoebill) + night drives","Uncrowded (NatGeo Best of the World 2026) and ~2 hours from Kigali - fly in the morning, game-drive by lunch; completes the 3-park Rwanda circuit with Volcanoes (gorillas) + Nyungwe (chimps)","US L3 Reconsider Travel (2026 regional Ebola-alert; was L2) - Akagera is EASTERN Rwanda, far from the 10km DRC-border L4 carve-out; disclose L3 + consent","Fees 2026: $100/adult, $50/child; sleeping in-park halves the fee nights 2-3 and is FREE from night 4 (up to a week) - a real reason to stay; best Jun-Sep + Jan-Feb","Sold via Rwandan safari DMCs 10-15% - IATAN/host-gated, CLIA has NO Africa representation; African Parks fees bundle/pass-through; RWF (~1,467/USD); visa on arrival $30; malaria year-round in the lowland east; AMREF for evac"],"safety":{"emergency":"112 (police) / 912 ambulance / 111 fire; AMREF Flying Doctors for bush evac","hospital":"Remote (~2h from Kigali) - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Kigali","advisory_level":"L3","malaria":"present year-round in the lowland east (chloroquine-resistant) - prophylaxis advised; DEET at dawn/dusk","yellow_fever":"required only if arriving from a YF-endemic country (not direct from the US)","activity_note":"L3 DISCLOSE + CONSENT (2026 regional Ebola-alert; Akagera is eastern Rwanda, far from the DRC-border L4 carve-out). Dangerous game at close range - stay in the vehicle, follow the guide, never approach rhino. Lake Ihema boat safari: hippo pods + shoreline crocs - remain seated, limbs in the boat. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Rusizi District FCDO advises against all but essential travel to the parts of Rusizi District which are within 10km of the border with the Democratic Republic of Congo (DRC), including the Rwandan islands in Lake Kivu and Kamembe Airport."},{"form":"against all but essential travel","text":"advises against all but essential travel to parts of the Rubavu and Rusizi Districts."}],"url":"https://www.gov.uk/foreign-travel-advice/rwanda","read":"2026-08-19","page_updated":"2026-06-10T15:14:19+01:00"}},"timing":{"peak":"Jun-Sep (esp Jul-Aug, dry, wildlife at water) + Dec holiday","shoulder":"Oct-Nov + Mar (softer rates, good game)","green":"Jan-early Feb (fewer vehicles, lower lodge rates) + Apr-May (long rains, lush, cheapest)","booking_lead":"lodges (few, small) 2-5 mo for Jun-Sep; in-park stay-longer fee break (nights 2-3 half, 4+ free) rewards multi-night; green 1-2 mo","off_season_specials":"Jan-Feb + Apr-May value; the 3-park Rwanda circuit (Volcanoes + Nyungwe + Akagera) unlocks the Nov-May 30% gorilla-permit discount","event_peaks":"Jul-Aug + Christmas/NY; N-Hemisphere summer","campaign_start":"Jun-Sep 4-6 mo out; 3-park circuit (with the gorilla discount) by prior Aug-Sep; position as quiet accessible Big-Five vs crowded Serengeti/Mara"},"jewels":[{"name":"A Big-Five game drive (the comeback)","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$400-1,800/pp/day","timing":"Jun-Sep + Jan-Feb; dry best","draw_rank":1,"hook":"lion, black + white rhino, elephant, buffalo and leopard on rewilded plains — one of Africa''s great conservation success stories, with hardly another vehicle","si":"safari","blurb":"lion, black + white rhino, elephant, buffalo and leopard on rewilded plains — one of Africa''s great conservation success stories, with hardly another vehicle","when":"Jun-Sep + Jan-Feb; dry best","commission":"safari DMC 10-15%"},{"name":"Rhino tracking","si_tag":"safari","status":"live","tier":"premier","price_band":"within the safari","timing":"Jun-Sep  + Dec holiday","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"both black rhino and southern white rhino — Akagera is now one of the more reliable rhino parks in East Africa, guide-radio-coordinated","si":"safari","blurb":"both black rhino and southern white rhino — Akagera is now one of the more reliable rhino parks in East Africa, guide-radio-coordinated","when":"Jun-Sep  + Dec holiday","commission":"safari DMC 10-15%"},{"name":"The Lake Ihema boat safari","si_tag":"globaladv","status":"live","tier":"essential","price_band":"~$40-50/pp","timing":"Jun-Sep  + Dec holiday","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"large hippo pods + shoreline Nile crocodiles are the leading on-water hazards — remain seated, keep limbs in the boat","si":"adventure","blurb":"large hippo pods + shoreline Nile crocodiles are the leading on-water hazards — remain seated, keep limbs in the boat","when":"Jun-Sep  + Dec holiday","commission":"DMC/park"},{"name":"A night drive","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$40-60/pp","timing":"Jun-Sep  + Dec holiday","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the nocturnal cast — leopard, hyena, bushbaby, genet — on a guided after-dark drive, an experience the day misses","si":"adventure","blurb":"the nocturnal cast — leopard, hyena, bushbaby, genet — on a guided after-dark drive, an experience the day misses","when":"Jun-Sep  + Dec holiday","commission":"DMC/park"},{"name":"The African Parks conservation story","si_tag":"deepdive","status":"future","tier":"premier","price_band":"on application","timing":"Jun-Sep  + Dec holiday","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the rewilding of Akagera — from war-emptied to full Big Five under African Parks + the RDB, with the \"Rhino Rewild\" translocations","si":"deepdive","blurb":"the rewilding of Akagera — from war-emptied to full Big Five under African Parks + the RDB, with the \"Rhino Rewild\" translocations","when":"Jun-Sep  + Dec holiday","commission":"park/DMC"},{"name":"A Magashi Camp honeymoon","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$800-2,500+/night all-in","timing":"standing; peak 2-5 mo","draw_rank":1,"hook":"Wilderness''s tented lakeside camp on a game-rich peninsula — private guiding, boat safaris and Big Five from the doorstep","si":"ultra","blurb":"Wilderness''s tented lakeside camp on a game-rich peninsula — private guiding, boat safaris and Big Five from the doorstep","when":"standing; peak 2-5 mo","commission":"consortia/Virtuoso + DMC"},{"name":"An Akagera lakeside honeymoon","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Sep  + Dec holiday","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Sep  + Dec holiday","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for at Akagera?","a":"Dangerous game and the lake, plus the health advisory - not crime. Free-ranging lion, elephant and rhino at close range - stay in the vehicle and follow your guide; on the Lake Ihema boat safari keep seated among the hippo pods and shoreline crocs. Malaria is year-round in the lowland east (prophylaxis + DEET), and it''s remote - carry AMREF Flying Doctors + insurance.","source":"cdc.gov","si_tag":"safety"},{"q":"Is Akagera a real Big Five park?","a":"Yes - thanks to one of conservation''s great turnarounds. African Parks (managing with the RDB since 2010) brought back lions (2015) and rhinos (2017), and added white rhinos in 2021 and 2025 - restoring the full Big Five to a park that civil war had emptied.","source":"nationalgeographic.com","si_tag":"safari"},{"q":"When is the best time to visit Akagera?","a":"Jun-Sep and Jan-Feb (dry) - the bush thins, wildlife concentrates at water, and roads stay passable. Jan-early Feb is low season (fewer vehicles, lower lodge rates); the green rains bring lush scenery and birding.","source":"safaribookings.com","si_tag":"safari"},{"q":"How does Akagera fit a Rwanda trip, and is it worth it?","a":"Very much: Akagera is ~2 hours from Kigali, so it pairs naturally with the gorillas of Volcanoes and the chimps of Nyungwe into a 3-park Rwanda circuit - and staying in the park (nights 2-3 half-price, night 4+ free) rewards a longer stop.","source":"nationalgeographic.com","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for Rwanda?","a":"Visa on arrival $30 (or online via Irembo); passport valid 6 months. Yellow fever is required only if arriving from a YF-endemic country (not direct from the US).","source":"thingstodoinrwanda.com","si_tag":"safari"}],"seo":{"meta_title":"Akagera Safari Guide: Rwanda''s Big Five Comeback, Lake Ihema Boat Safari, Fees & Best Time","meta_description":"Plan an Akagera safari - Rwanda''s Big-Five savanna comeback under African Parks (lions, black + white rhinos rewilded), a Lake Ihema boat safari for hippos, crocs and the shoebill, uncrowded and 2 hours from Kigali - with real safety (US L3), timing, fees and the 3-park Rwanda circuit.","slug":"akagera-np-rwanda","primary_keyword":"Akagera National Park safari","long_tail":["Akagera Big Five Rwanda","Akagera boat safari Lake Ihema","Akagera rhino reintroduction","Akagera park fees 2026","Rwanda safari and gorillas","is Akagera safe","Akagera vs Serengeti"],"search_language":"fr","local_keywords":["Akagera","intare","inkura","Ihema","imvubu","African Parks","shoebill"],"hreflang":["en","fr"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-01"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","regional-ebola-alert"],"book_suppressed":false,"note":"Rwanda US L3 Reconsider Travel (2026 regional Ebola-alert precaution; was L2). Akagera is EASTERN Rwanda, far from the 10km DRC-border L4 carve-out (which applies to Volcanoes/NW). Disclose L3 + confirm consent. Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-08-01","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - Big-Five game drives primary; Lake Ihema boat safari + night drives = globaladv; African Parks/Rhino-Rewild conservation = deepdive; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"Big Five game drives"},{"si":"globaladv","name":"adventure","status":"live","note":"Lake Ihema boat safari + night drives"},{"si":"ultra","name":"ultra","status":"live","note":"Magashi Camp (Wilderness)"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"African Parks / Rhino Rewild conservation"}],"ultra":[{"name":"Magashi Camp (Wilderness) - Akagera''s apex stay","why_ultra":"a tented lakeside camp on a game-rich peninsula, private guiding, boat safaris + the Big Five at the door","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,500-2,500+/night"},{"name":"A private Big-Five + boat + rhino-conservation day","why_ultra":"exclusive-vehicle Big Five game drive + the Lake Ihema boat safari + a behind-the-scenes African Parks conservation visit, privately guided","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"The 3-park luxury Rwanda circuit (Volcanoes + Nyungwe + Akagera)","why_ultra":"gorillas + chimps/canopy walk + the Big-Five savanna, private-guided - and it unlocks the Nov-May 30% gorilla-permit discount","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-01","hero":{"query":"Akagera National Park, Rwanda"},"geo":{"lat":-1.65,"lng":30.7}}'::jsonb, 3),
  ('amboseli-kenya', '05A', 'Amboseli National Park', 'Kenya', 'Elephants under Kilimanjaro', 'live', 'verified', 'elephant', 'Kenya — Amboseli / Kilimanjaro views', '{"safari","ultra","romance","adventure","deepdive","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Elephants under Kilimanjaro - the most iconic backdrop in safari: 1,600+ free-ranging elephants incl. some of the last Super Tuskers; the best Kilimanjaro (5,896m) views are from Amboseli (clearest at dawn Jun-Oct + Jan-Feb, before ~10am cloud)","Four of the Big Five (elephant, lion, buffalo, leopard) - NO rhino (hunted to local extinction 1970s); pair with Laikipia (Ol Pejeta/Lewa) for rhino","The Amboseli Elephant Research Project (founded 1972 by Cynthia Moss) - the longest wild-elephant study on Earth, 3,500+ individuals, matriarchal society; snowmelt swamps + 400+ birds","US L2 Exercise Increased Caution (elevated risk Nairobi/urban, not Amboseli); KWS fee $70/24-hour (proposed $90 under court review); cost ~$400-850/pp/day comfortable-premium, ~$900-2,000 luxury","Sold via Kenya safari DMCs ~10-16%+ - IATAN/host-gated, CLIA has NO Africa representation; KWS fees non-commissionable pass-through; AMREF Flying Doctors for evac","KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; malaria prophylaxis advised (chloroquine-resistant); YF only if arriving from a risk country"],"safety":{"emergency":"999 / 112 / 911 (reliable in cities, weak remote); Kenya Red Cross ambulance 1199; AMREF Flying Doctors for bush evac","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Nairobi","advisory_level":"L2","malaria":"prophylaxis advised (CDC - Amboseli qualifies, chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory only if arriving from a risk country; CDC recommends for most","activity_note":"L2 disclose (elevated risk is Nairobi/urban, not Amboseli). Free-ranging elephants at close range 